'use client';
import React, { useState } from 'react';
import PhoneInputWithCountry, { validatePhone } from './PhoneInputWithCountry';
import { isDemoContact, trackGenericLeadConversion, getStoredUtmParams } from '@/lib/tracking';

const inputStyle = { backgroundColor: '#02042d', border: '1px solid rgba(224,201,150,0.3)', color: '#f8f6f0', fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '15px' };
const inputFocusStyle = (e: any) => e.target.style.border = '1px solid rgba(224,201,150,0.8)';
const inputBlurStyle = (e: any) => e.target.style.border = '1px solid rgba(224,201,150,0.3)';
export default function ContactPageFormSection() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [submitError, setSubmitError] = useState(false);
  const [phoneValue, setPhoneValue] = useState('');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const target = e.target as typeof e.target & {
      firstName: { value: string };
      lastName: { value: string };
      phone: { value: string };
      email: { value: string };
      message: { value: string };
    };

    const phoneParts = target.phone.value.split(' ');
    const code = phoneParts[0]?.startsWith('+') ? phoneParts[0] : '+61';
    const num = phoneParts.slice(1).join('') || target.phone.value;
    const phoneVal = validatePhone(code, num);

    if (!phoneVal.isValid && target.phone.value) {
      alert(phoneVal.errorReason || 'Please enter a valid mobile phone number.');
      return;
    }

    setIsSubmitting(true);
    setSubmitError(false);

    const formData = {
      firstName: target.firstName.value,
      lastName: target.lastName.value,
      phone: target.phone.value,
      email: target.email.value,
      message: target.message.value,
    };
    
    const isDemo = isDemoContact(formData);
    
    try {
      const utm = getStoredUtmParams();
      const eventId = trackGenericLeadConversion({
        formName: 'Contact Page Form',
        userEmail: formData.email,
        userPhone: formData.phone,
        userName: `${formData.firstName} ${formData.lastName}`.trim(),
        customGoogleAdsLabel: 'AW-18364005209/LYVeCM6gpMIcEN6ok4FE',
      });

      if (!isDemo) {
        // Send to Next.js API (triggers Meta CAPI on server)
        await fetch('/api/send-mail', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, utm, eventId, formType: 'contact' }),
        }).catch(() => {});

        // Send to PHP mailer fallback
        await fetch('/send-mail.php', {
          method: 'POST',
          body: JSON.stringify(formData),
          headers: { 'Content-Type': 'application/json' },
        }).catch(() => {});
      } else {
        console.log('[Demo Contact Detected] Bypassing Email dispatch.');
      }

      setSubmitted(true);
      const formEl = e.target as HTMLFormElement;
      setTimeout(() => {
        if (typeof window !== 'undefined') {
          window.location.href = '/thank-you?type=contact';
        }
      }, 1000);
    } catch (err) {
      console.error("Error sending mail", err);
      setSubmitError(true);
      setTimeout(() => setSubmitError(false), 4000);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <section id="contact-form" className="relative w-full py-24 px-6 md:px-12 flex items-center justify-center overflow-hidden" style={{ minHeight: '100vh' }}>
      {/* Background Image */}
      <div className="absolute inset-0 w-full h-full">
        <img 
          src="/assets/images/photo-1600596542815-ffad4c1539a9.webp" 
          alt="Contact Background Interior" 
          fetchPriority="high"
          className="w-full h-full object-cover"
        />
        <div className="absolute inset-0 bg-[#02042d]/20"></div>
      </div>

      {/* Main Card */}
      <div className="relative z-10 w-full max-w-[1200px] flex flex-col md:flex-row shadow-2xl" style={{ backgroundColor: '#02042d', padding: 'clamp(40px, 6vw, 80px) clamp(32px, 5vw, 64px)' }}>
        
        {/* Left Side */}
        <div className="flex-1 md:pr-16 md:border-r border-white/10 flex flex-col justify-center">
          <div className="flex flex-col gap-6 md:gap-8">
            <h1 style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: 'clamp(36px, 4.2vw, 56px)', color: '#f8f6f0', lineHeight: 1.1, margin: 0, letterSpacing: '-1.5px' }}>
              Building Your Portfolio,<br/>Property by Property.
            </h1>
            <p style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: 'clamp(15px, 1.2vw, 18px)', color: 'rgba(248,246,240,0.85)', lineHeight: 1.6, margin: 0, maxWidth: '420px' }}>
              Have a project in mind or need expert guidance on UAE off‑plan investment? We would love to hear from you. Reach out for enquiries, project recommendations or a free consultation.
            </p>
            <div style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0', lineHeight: 1.6, marginTop: '10px' }}>
              <p className="m-0 pb-1 font-medium" style={{ color: '#f8f6f0', fontSize: 'clamp(16px, 1.3vw, 19px)' }}>WeNest Real Estate LLC</p>
              <p className="m-0 mb-4" style={{ color: 'rgba(248,246,240,0.85)', fontSize: 'clamp(14px, 1.1vw, 16px)' }}>Property Investment Office 4 - Dubai Investment Park First - Dubai - United Arab Emirates</p>

              <div className="flex flex-col gap-2" style={{ color: '#f8f6f0', fontSize: 'clamp(16px, 1.3vw, 20px)' }}>
                <div>
                  <a href="mailto:info@wenestre.com" className="hover:underline" style={{ color: '#e0c996' }}>info@wenestre.com</a>
                </div>
                <div>
                  <span style={{ opacity: 0.9 }}>Phone / WhatsApp: </span>
                  <a href="tel:+971541511512" className="hover:underline" style={{ whiteSpace: 'nowrap' }}>+971 54 151 1512</a>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side - Form */}
        <div className="flex-1 md:pl-16 pt-12 md:pt-0 flex flex-col justify-center relative -top-2">
          <form className="flex flex-col gap-6" onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="flex flex-col gap-2">
                <label className="text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0' }}>First Name</label>
                <input type="text" name="firstName" required placeholder="Ahmed" className="w-full px-5 py-4 placeholder-white/30 outline-none transition-colors" style={inputStyle} onFocus={inputFocusStyle} onBlur={inputBlurStyle} />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0' }}>Last Name</label>
                <input type="text" name="lastName" required placeholder="Al Mansoori" className="w-full px-5 py-4 placeholder-white/30 outline-none transition-colors" style={inputStyle} onFocus={inputFocusStyle} onBlur={inputBlurStyle} />
              </div>
            </div>
            
            <div className="flex flex-col gap-2">
              <label className="text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0' }}>Phone Number</label>
              <PhoneInputWithCountry
                id="contact-phone"
                value={phoneValue}
                onChange={val => setPhoneValue(val || "")}
                inputClassName="w-full px-5 py-4 placeholder-white/30 outline-none transition-colors"
                inputStyle={inputStyle}
                onFocus={inputFocusStyle}
                onBlur={inputBlurStyle}
                placeholder="50 000 0000"
                required
                theme="dark"
              />
            </div>

            <div className="flex flex-col gap-2">
              <label className="text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0' }}>Email</label>
              <input type="email" name="email" required placeholder="ahmed@gmail.com" className="w-full px-5 py-4 placeholder-white/30 outline-none transition-colors" style={inputStyle} onFocus={inputFocusStyle} onBlur={inputBlurStyle} />
            </div>
            
            <div className="flex flex-col gap-2">
              <label className="text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', color: '#f8f6f0' }}>Message</label>
              <textarea name="message" required placeholder="Write your message here" style={{ minHeight: '120px', ...inputStyle }} className="w-full px-5 py-4 placeholder-white/30 outline-none transition-colors resize-none" onFocus={inputFocusStyle} onBlur={inputBlurStyle}></textarea>
            </div>
            
            <button 
              type="submit"
              disabled={isSubmitting || submitted}
              className={`w-full font-medium py-4 mt-2 transition-all duration-300 ease-out border ${
                submitError
                  ? 'bg-red-900 border-red-900 text-white'
                  : submitted 
                  ? 'bg-transparent border-[#e0c996] text-[#e0c996]' 
                  : 'bg-[#02042d] border-[#e0c996] text-[#e0c996] hover:bg-transparent hover:border-[#e0c996]'
              }`} 
              style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '16px', borderRadius: '0px' }}
            >
              {isSubmitting ? 'Sending...' : submitError ? 'Failed to Send - Try Again' : submitted ? "✓ We'll Reach You Soon" : 'Submit'}
            </button>
          </form>
        </div>
      </div>
    </section>
  );
}
